from __future__ import annotations

from copy import deepcopy
from typing import Any
from uuid import uuid4


KV_FIELD_TYPE = "kv"
KV_STAGE_ADMIN = "admin"
KV_STAGE_PROJECT = "project"
KV_STAGE_TASK = "task"

KV_ALLOWED_STAGES = {
    KV_STAGE_ADMIN,
    KV_STAGE_PROJECT,
    KV_STAGE_TASK,
}

KV_TEXT_KEYS = ("key", "value", "remark", "remark2", "remark3")
KV_DEFAULT_REMARK_LABEL = "备注"
KV_DEFAULT_REMARK2_LABEL = "备注2"
KV_DEFAULT_REMARK3_LABEL = "备注3"
KV_TEXT_LABELS = {
    "key": "键",
    "value": "值",
    "remark": KV_DEFAULT_REMARK_LABEL,
    "remark2": KV_DEFAULT_REMARK2_LABEL,
    "remark3": KV_DEFAULT_REMARK3_LABEL,
}
KV_INPUT_MODE_DIRECT = "direct"
KV_INPUT_MODE_ENUM = "enum"
KV_ALLOWED_INPUT_MODES = {KV_INPUT_MODE_DIRECT, KV_INPUT_MODE_ENUM}


class KVValidationError(ValueError):
    """Raised when kv field data violates the schema or stage rules."""


def is_kv_field(field: Any) -> bool:
    return getattr(field, "field_type", None) == KV_FIELD_TYPE


def create_default_kv_column_configs() -> dict[str, dict[str, Any]]:
    return {
        key_name: {"input_mode": KV_INPUT_MODE_DIRECT, "enum_set_id": None}
        for key_name in KV_TEXT_KEYS
    }


def get_kv_column_config_enum_ids(column_configs: Any) -> set[int]:
    normalized = normalize_kv_column_configs(column_configs)
    return {
        config["enum_set_id"]
        for config in normalized.values()
        if config["input_mode"] == KV_INPUT_MODE_ENUM
        and config["enum_set_id"] is not None
    }


def normalize_kv_column_configs(
    column_configs: Any,
    *,
    existing_configs: Any | None = None,
    enum_set_map: dict[int, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    base_configs = create_default_kv_column_configs()
    existing_source = existing_configs if isinstance(existing_configs, dict) else {}
    incoming_source = column_configs if isinstance(column_configs, dict) else {}
    normalized_configs = {}

    for key_name in KV_TEXT_KEYS:
        existing_column = (
            existing_source.get(key_name)
            if isinstance(existing_source.get(key_name), dict)
            else {}
        )
        incoming_column = (
            incoming_source.get(key_name)
            if isinstance(incoming_source.get(key_name), dict)
            else {}
        )

        input_mode = incoming_column.get(
            "input_mode",
            existing_column.get("input_mode", base_configs[key_name]["input_mode"]),
        )
        if input_mode not in KV_ALLOWED_INPUT_MODES:
            raise KVValidationError(f"{KV_TEXT_LABELS[key_name]}列输入方式不合法")

        enum_set_id = _normalize_optional_int(
            incoming_column.get(
                "enum_set_id",
                existing_column.get(
                    "enum_set_id", base_configs[key_name]["enum_set_id"]
                ),
            ),
            f"{KV_TEXT_LABELS[key_name]}列枚举",
        )

        if input_mode == KV_INPUT_MODE_ENUM:
            if enum_set_id is None:
                raise KVValidationError(f"{KV_TEXT_LABELS[key_name]}列必须选择枚举")
            if enum_set_map is not None and enum_set_id not in enum_set_map:
                raise KVValidationError(f"{KV_TEXT_LABELS[key_name]}列引用的枚举不存在")
        else:
            enum_set_id = None

        normalized_configs[key_name] = {
            "input_mode": input_mode,
            "enum_set_id": enum_set_id,
        }

    return normalized_configs


def hydrate_kv_column_configs(
    column_configs: Any,
    *,
    enum_set_map: dict[int, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    normalized_configs = normalize_kv_column_configs(column_configs)
    enum_set_map = enum_set_map or {}
    hydrated_configs = {}

    for key_name, config in normalized_configs.items():
        enum_set = enum_set_map.get(config["enum_set_id"])
        hydrated_configs[key_name] = {
            **config,
            "enum_set_code": enum_set.code if enum_set else None,
            "enum_set_name": enum_set.name if enum_set else None,
            "enum_options": enum_set.options if enum_set else [],
        }

    return hydrated_configs


def normalize_kv_field_config(
    payload: dict[str, Any],
    existing_field: Any | None = None,
    *,
    enum_set_map: dict[int, Any] | None = None,
) -> dict[str, Any]:
    field_type = payload.get(
        "field_type",
        getattr(existing_field, "field_type", None),
    )

    if field_type != KV_FIELD_TYPE:
        return {
            "default_value": payload.get(
                "default_value",
                getattr(existing_field, "default_value", None),
            ),
            "kv_key_label": None,
            "kv_value_label": None,
            "kv_remark_label": None,
            "kv_remark2_label": None,
            "kv_remark3_label": None,
            "kv_column_configs": None,
            "kv_default_rows": None,
        }

    kv_key_label = _normalize_required_text(
        payload.get("kv_key_label", getattr(existing_field, "kv_key_label", None)),
        "键名标签",
    )
    kv_value_label = _normalize_required_text(
        payload.get(
            "kv_value_label",
            getattr(existing_field, "kv_value_label", None),
        ),
        "值名标签",
    )
    kv_remark_label = _normalize_required_text(
        payload.get(
            "kv_remark_label",
            getattr(existing_field, "kv_remark_label", None) or KV_DEFAULT_REMARK_LABEL,
        ),
        "备注标签",
    )
    kv_remark2_label = _normalize_required_text(
        payload.get(
            "kv_remark2_label",
            getattr(existing_field, "kv_remark2_label", None)
            or KV_DEFAULT_REMARK2_LABEL,
        ),
        "备注2标签",
    )
    kv_remark3_label = _normalize_required_text(
        payload.get(
            "kv_remark3_label",
            getattr(existing_field, "kv_remark3_label", None)
            or KV_DEFAULT_REMARK3_LABEL,
        ),
        "备注3标签",
    )
    kv_column_configs = normalize_kv_column_configs(
        payload.get("kv_column_configs"),
        existing_configs=getattr(existing_field, "kv_column_configs", None),
        enum_set_map=enum_set_map,
    )
    hydrated_column_configs = hydrate_kv_column_configs(
        kv_column_configs,
        enum_set_map=enum_set_map,
    )
    raw_rows = payload.get(
        "kv_default_rows",
        deepcopy(getattr(existing_field, "kv_default_rows", None)),
    )

    return {
        "default_value": None,
        "kv_key_label": kv_key_label,
        "kv_value_label": kv_value_label,
        "kv_remark_label": kv_remark_label,
        "kv_remark2_label": kv_remark2_label,
        "kv_remark3_label": kv_remark3_label,
        "kv_column_configs": kv_column_configs,
        "kv_default_rows": normalize_kv_default_rows(
            raw_rows,
            column_configs=hydrated_column_configs,
        ),
    }


def normalize_kv_default_rows(
    rows: Any,
    *,
    column_configs: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_rows = []
    seen_row_ids: set[str] = set()

    for index, raw_row in enumerate(_ensure_row_list(rows), start=1):
        row_id = _normalize_optional_text(
            raw_row.get("row_id"), "row_id"
        ) or _generate_row_id(KV_STAGE_ADMIN)
        source_stage = raw_row.get("source_stage") or KV_STAGE_ADMIN

        if source_stage != KV_STAGE_ADMIN:
            raise KVValidationError(f"第 {index} 行的来源必须为 admin")
        if row_id in seen_row_ids:
            raise KVValidationError(f"第 {index} 行的 row_id 重复")

        normalized_rows.append(
            {
                "row_id": row_id,
                "key": _normalize_kv_text_value(
                    raw_row.get("key"),
                    key_name="key",
                    field_name=f"第 {index} 行的键",
                    column_configs=column_configs,
                ),
                "value": _normalize_kv_text_value(
                    raw_row.get("value"),
                    key_name="value",
                    field_name=f"第 {index} 行的值",
                    column_configs=column_configs,
                ),
                "remark": _normalize_kv_text_value(
                    raw_row.get("remark"),
                    key_name="remark",
                    field_name=f"第 {index} 行的备注",
                    column_configs=column_configs,
                ),
                "remark2": _normalize_kv_text_value(
                    raw_row.get("remark2"),
                    key_name="remark2",
                    field_name=f"第 {index} 行的备注2",
                    column_configs=column_configs,
                ),
                "remark3": _normalize_kv_text_value(
                    raw_row.get("remark3"),
                    key_name="remark3",
                    field_name=f"第 {index} 行的备注3",
                    column_configs=column_configs,
                ),
                "enabled": _normalize_bool(
                    raw_row.get("enabled"), f"第 {index} 行的是否使用"
                ),
                "allow_child_toggle_enabled": _normalize_bool(
                    raw_row.get("allow_child_toggle_enabled"),
                    f"第 {index} 行的下级修改权限",
                ),
                "source_stage": KV_STAGE_ADMIN,
            }
        )
        seen_row_ids.add(row_id)

    return normalized_rows


def normalize_kv_stage_rows(
    submitted_rows: Any,
    inherited_rows: Any,
    *,
    stage: str,
    allow_new_rows: bool,
    required: bool,
    column_configs: Any | None = None,
) -> list[dict[str, Any]]:
    if stage not in {KV_STAGE_PROJECT, KV_STAGE_TASK}:
        raise KVValidationError(f"不支持的阶段: {stage}")

    allowed_inherited_stages = {KV_STAGE_ADMIN}
    if stage == KV_STAGE_TASK:
        allowed_inherited_stages.add(KV_STAGE_PROJECT)

    normalized_inherited = _normalize_reference_rows(
        inherited_rows,
        allowed_source_stages=allowed_inherited_stages,
        column_configs=column_configs,
    )
    inherited_by_id = {row["row_id"]: row for row in normalized_inherited}

    if submitted_rows is None:
        rows_to_process = deepcopy(normalized_inherited)
    else:
        rows_to_process = _ensure_row_list(submitted_rows)

    normalized_rows = []
    seen_row_ids: set[str] = set()
    inherited_seen: set[str] = set()

    for index, raw_row in enumerate(rows_to_process, start=1):
        row_id = _normalize_optional_text(raw_row.get("row_id"), "row_id")

        if row_id and row_id in inherited_by_id:
            row = _normalize_inherited_row_submission(
                raw_row,
                inherited_by_id[row_id],
                index=index,
                allow_edit=allow_new_rows,
                stage=stage,
                column_configs=column_configs,
            )
            inherited_seen.add(row_id)
        else:
            row = _normalize_new_stage_row(
                raw_row,
                stage=stage,
                allow_new_rows=allow_new_rows,
                index=index,
                column_configs=column_configs,
            )

        if row["row_id"] in seen_row_ids:
            raise KVValidationError(f"第 {index} 行的 row_id 重复")

        seen_row_ids.add(row["row_id"])
        normalized_rows.append(row)

    return normalized_rows


def _normalize_reference_rows(
    rows: Any,
    *,
    allowed_source_stages: set[str],
    column_configs: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_rows = []
    seen_row_ids: set[str] = set()

    for index, raw_row in enumerate(_ensure_row_list(rows), start=1):
        row_id = _normalize_required_text(
            raw_row.get("row_id"), f"第 {index} 行的 row_id"
        )
        source_stage = _normalize_required_text(
            raw_row.get("source_stage"),
            f"第 {index} 行的来源",
        )

        if source_stage not in allowed_source_stages:
            raise KVValidationError(f"第 {index} 行的来源不合法")
        if row_id in seen_row_ids:
            raise KVValidationError(f"第 {index} 行的 row_id 重复")

        normalized_rows.append(
            {
                "row_id": row_id,
                "key": _normalize_kv_text_value(
                    raw_row.get("key"),
                    key_name="key",
                    field_name=f"第 {index} 行的键",
                    column_configs=column_configs,
                ),
                "value": _normalize_kv_text_value(
                    raw_row.get("value"),
                    key_name="value",
                    field_name=f"第 {index} 行的值",
                    column_configs=column_configs,
                ),
                "remark": _normalize_kv_text_value(
                    raw_row.get("remark"),
                    key_name="remark",
                    field_name=f"第 {index} 行的备注",
                    column_configs=column_configs,
                ),
                "remark2": _normalize_kv_text_value(
                    raw_row.get("remark2"),
                    key_name="remark2",
                    field_name=f"第 {index} 行的备注2",
                    column_configs=column_configs,
                ),
                "remark3": _normalize_kv_text_value(
                    raw_row.get("remark3"),
                    key_name="remark3",
                    field_name=f"第 {index} 行的备注3",
                    column_configs=column_configs,
                ),
                "enabled": _normalize_bool(
                    raw_row.get("enabled"), f"第 {index} 行的是否使用"
                ),
                "allow_child_toggle_enabled": _normalize_bool(
                    raw_row.get("allow_child_toggle_enabled"),
                    f"第 {index} 行的下级修改权限",
                ),
                "source_stage": source_stage,
            }
        )
        seen_row_ids.add(row_id)

    return normalized_rows


def _normalize_inherited_row_submission(
    raw_row: dict[str, Any],
    base_row: dict[str, Any],
    *,
    index: int,
    allow_edit: bool = False,
    stage: str,
    column_configs: Any | None = None,
) -> dict[str, Any]:
    source_stage = raw_row.get("source_stage", base_row["source_stage"])
    if not allow_edit and source_stage != base_row["source_stage"]:
        raise KVValidationError(f"第 {index} 行不能修改来源")

    allow_child = raw_row.get(
        "allow_child_toggle_enabled",
        base_row["allow_child_toggle_enabled"],
    )
    allow_child = _normalize_bool(allow_child, f"第 {index} 行的下级修改权限")
    if allow_child != base_row["allow_child_toggle_enabled"]:
        raise KVValidationError(f"第 {index} 行不能修改下级修改权限")

    if allow_edit:
        normalized_row = deepcopy(base_row)
        for key_name in KV_TEXT_KEYS:
            raw_value = raw_row.get(key_name, base_row[key_name])
            normalized_value = _normalize_kv_text_value(
                raw_value,
                key_name=key_name,
                field_name=f"第 {index} 行的{KV_TEXT_LABELS[key_name]}",
                column_configs=column_configs,
            )
            normalized_row[key_name] = normalized_value
        normalized_row["source_stage"] = stage
    else:
        for key_name in KV_TEXT_KEYS:
            raw_value = raw_row.get(key_name, base_row[key_name])
            normalized_value = _normalize_kv_text_value(
                raw_value,
                key_name=key_name,
                field_name=f"第 {index} 行的{KV_TEXT_LABELS[key_name]}",
                column_configs=column_configs,
            )
            if normalized_value != base_row[key_name]:
                raise KVValidationError(
                    f"第 {index} 行不能修改继承的{KV_TEXT_LABELS[key_name]}"
                )
        normalized_row = deepcopy(base_row)

    enabled = _normalize_bool(
        raw_row.get("enabled", base_row["enabled"]),
        f"第 {index} 行的是否使用",
    )
    if not base_row["allow_child_toggle_enabled"] and enabled != base_row["enabled"]:
        raise KVValidationError(f"第 {index} 行不允许修改是否使用")

    normalized_row["enabled"] = enabled
    return normalized_row


def _normalize_new_stage_row(
    raw_row: dict[str, Any],
    *,
    stage: str,
    allow_new_rows: bool,
    index: int,
    column_configs: Any | None = None,
) -> dict[str, Any]:
    if not allow_new_rows:
        raise KVValidationError("当前阶段不允许新增表格行")

    source_stage = raw_row.get("source_stage") or stage
    if source_stage != stage:
        raise KVValidationError(f"第 {index} 行的来源必须为 {stage}")

    row_id = _normalize_optional_text(
        raw_row.get("row_id"), "row_id"
    ) or _generate_row_id(stage)
    allow_child_toggle_enabled = False
    if stage == KV_STAGE_PROJECT:
        allow_child_toggle_enabled = _normalize_bool(
            raw_row.get("allow_child_toggle_enabled"),
            f"第 {index} 行的下级修改权限",
        )

    return {
        "row_id": row_id,
        "key": _normalize_kv_text_value(
            raw_row.get("key"),
            key_name="key",
            field_name=f"第 {index} 行的键",
            column_configs=column_configs,
        ),
        "value": _normalize_kv_text_value(
            raw_row.get("value"),
            key_name="value",
            field_name=f"第 {index} 行的值",
            column_configs=column_configs,
        ),
        "remark": _normalize_kv_text_value(
            raw_row.get("remark"),
            key_name="remark",
            field_name=f"第 {index} 行的备注",
            column_configs=column_configs,
        ),
        "remark2": _normalize_kv_text_value(
            raw_row.get("remark2"),
            key_name="remark2",
            field_name=f"第 {index} 行的备注2",
            column_configs=column_configs,
        ),
        "remark3": _normalize_kv_text_value(
            raw_row.get("remark3"),
            key_name="remark3",
            field_name=f"第 {index} 行的备注3",
            column_configs=column_configs,
        ),
        "enabled": _normalize_bool(raw_row.get("enabled"), f"第 {index} 行的是否使用"),
        "allow_child_toggle_enabled": allow_child_toggle_enabled,
        "source_stage": stage,
    }


def _ensure_row_list(rows: Any) -> list[dict[str, Any]]:
    if rows is None:
        return []
    if not isinstance(rows, list):
        raise KVValidationError("五列表格字段必须使用数组")

    normalized_rows = []
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, dict):
            raise KVValidationError(f"第 {index} 行的数据格式不正确")
        normalized_rows.append(row)
    return normalized_rows


def _normalize_required_text(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise KVValidationError(f"{field_name}必须为字符串")

    normalized = value.strip()
    if not normalized:
        raise KVValidationError(f"{field_name}不能为空")
    return normalized


def _normalize_optional_text(value: Any, field_name: str) -> str:
    if value is None:
        return ""
    if not isinstance(value, str):
        raise KVValidationError(f"{field_name}必须为字符串")
    return value.strip()


def _normalize_optional_int(value: Any, field_name: str) -> int | None:
    if value in (None, ""):
        return None
    if isinstance(value, bool) or not isinstance(value, int):
        raise KVValidationError(f"{field_name}必须为整数")
    if value <= 0:
        raise KVValidationError(f"{field_name}必须为正整数")
    return value


def _get_kv_column_runtime_config(
    column_configs: Any,
    key_name: str,
) -> dict[str, Any]:
    normalized_configs = (
        column_configs
        if isinstance(column_configs, dict)
        else create_default_kv_column_configs()
    )
    config = normalized_configs.get(key_name)
    if not isinstance(config, dict):
        return {
            "input_mode": KV_INPUT_MODE_DIRECT,
            "enum_set_id": None,
            "enum_set_name": None,
            "enum_set_code": None,
            "enum_options": [],
        }
    return {
        "input_mode": config.get("input_mode", KV_INPUT_MODE_DIRECT),
        "enum_set_id": config.get("enum_set_id"),
        "enum_set_name": config.get("enum_set_name"),
        "enum_set_code": config.get("enum_set_code"),
        "enum_options": list(config.get("enum_options") or []),
    }


def _normalize_kv_text_value(
    value: Any,
    *,
    key_name: str,
    field_name: str,
    column_configs: Any,
) -> str:
    if key_name in {"remark", "remark2", "remark3"}:
        normalized = _normalize_optional_text(value, field_name)
    else:
        normalized = _normalize_required_text(value, field_name)

    runtime_config = _get_kv_column_runtime_config(column_configs, key_name)
    if runtime_config["input_mode"] != KV_INPUT_MODE_ENUM:
        return normalized

    if not normalized:
        return normalized

    enum_options = runtime_config["enum_options"]
    if normalized not in enum_options:
        enum_name = runtime_config["enum_set_name"] or KV_TEXT_LABELS[key_name]
        raise KVValidationError(f"{field_name}必须从枚举“{enum_name}”中选择")

    return normalized


def _normalize_bool(value: Any, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise KVValidationError(f"{field_name}必须为布尔值")
    return value


def _generate_row_id(stage: str) -> str:
    if stage not in KV_ALLOWED_STAGES:
        raise KVValidationError(f"不支持的阶段: {stage}")
    return f"{stage}-{uuid4()}"

from __future__ import annotations

from copy import deepcopy
from typing import Any

from app import db
from app.models import KVEnumSet, TaskGroup, project_functions
from app.utils.kv_fields import (
    KV_FIELD_TYPE,
    KV_STAGE_ADMIN,
    KV_STAGE_PROJECT,
    KV_STAGE_TASK,
    KVValidationError,
    get_kv_column_config_enum_ids,
    hydrate_kv_column_configs,
    is_kv_field,
    normalize_kv_default_rows,
    normalize_kv_stage_rows,
)


def _resolve_enum_set_map(
    column_configs: Any,
    *,
    enum_set_overrides: dict[int, Any] | None = None,
) -> dict[int, Any]:
    enum_set_ids = get_kv_column_config_enum_ids(column_configs)
    if enum_set_overrides:
        enum_set_ids.update(enum_set_overrides.keys())

    enum_sets = (
        KVEnumSet.query.filter(KVEnumSet.id.in_(enum_set_ids)).all()
        if enum_set_ids
        else []
    )
    enum_set_map = {enum_set.id: enum_set for enum_set in enum_sets}
    if enum_set_overrides:
        enum_set_map.update(enum_set_overrides)
    return enum_set_map


def ensure_kv_usage_compatible(
    field: Any,
    *,
    proposed_default_rows: Any | None = None,
    proposed_column_configs: Any | None = None,
    proposed_required: bool | None = None,
    proposed_fill_stage_project: bool | None = None,
    proposed_fill_stage_task: bool | None = None,
    enum_set_overrides: dict[int, Any] | None = None,
) -> None:
    if not is_kv_field(field):
        return

    column_configs = (
        proposed_column_configs
        if proposed_column_configs is not None
        else deepcopy(field.kv_column_configs)
    )
    enum_set_map = _resolve_enum_set_map(
        column_configs,
        enum_set_overrides=enum_set_overrides,
    )
    hydrated_column_configs = hydrate_kv_column_configs(
        column_configs,
        enum_set_map=enum_set_map,
    )

    default_rows = normalize_kv_default_rows(
        proposed_default_rows
        if proposed_default_rows is not None
        else deepcopy(field.kv_default_rows or []),
        column_configs=hydrated_column_configs,
    )
    required = field.required if proposed_required is None else proposed_required
    fill_stage_project = (
        field.fill_stage_project
        if proposed_fill_stage_project is None
        else proposed_fill_stage_project
    )
    fill_stage_task = (
        field.fill_stage_task
        if proposed_fill_stage_task is None
        else proposed_fill_stage_task
    )

    bindings = (
        db.session.execute(
            db.select(project_functions).where(
                project_functions.c.function_config_id == field.function_config_id,
            )
        )
        .mappings()
        .all()
    )
    for binding in bindings:
        pm_fields = (
            binding["pm_fields"] if isinstance(binding["pm_fields"], dict) else {}
        )
        if field.json_key not in pm_fields:
            continue

        normalized_project_rows = _coerce_legacy_inherited_rows(
            pm_fields[field.json_key],
            default_rows,
        )

        try:
            normalize_kv_stage_rows(
                normalized_project_rows,
                default_rows,
                stage=KV_STAGE_PROJECT,
                allow_new_rows=fill_stage_project,
                required=required,
                column_configs=hydrated_column_configs,
            )
        except KVValidationError as exc:
            raise KVValidationError(
                f"项目 #{binding['project_id']} 中字段“{field.label}”的已保存数据与当前配置冲突：{exc}"
            ) from exc

    task_groups = TaskGroup.query.filter_by(
        function_config_id=field.function_config_id
    ).all()
    for task_group in task_groups:
        inputs = task_group.inputs if isinstance(task_group.inputs, dict) else {}
        if field.json_key not in inputs:
            continue

        inherited_rows = _extract_task_inherited_rows(inputs[field.json_key])
        if not inherited_rows:
            inherited_rows = default_rows

        normalized_task_rows = _coerce_legacy_inherited_rows(
            inputs[field.json_key],
            inherited_rows,
        )

        try:
            normalize_kv_stage_rows(
                normalized_task_rows,
                inherited_rows,
                stage=KV_STAGE_TASK,
                allow_new_rows=fill_stage_task,
                required=required,
                column_configs=hydrated_column_configs,
            )
        except KVValidationError as exc:
            raise KVValidationError(
                f"任务组 #{task_group.id} 中字段“{field.label}”的已保存数据与当前配置冲突：{exc}"
            ) from exc


def ensure_kv_default_rows_locked(
    field: Any,
    *,
    proposed_default_rows: Any | None = None,
    proposed_column_configs: Any | None = None,
    enum_set_overrides: dict[int, Any] | None = None,
) -> None:
    if not is_kv_field(field):
        return

    usage_target = _find_saved_kv_usage_target(field)
    if usage_target is None:
        return

    column_configs = (
        proposed_column_configs
        if proposed_column_configs is not None
        else deepcopy(field.kv_column_configs)
    )
    enum_set_map = _resolve_enum_set_map(
        column_configs,
        enum_set_overrides=enum_set_overrides,
    )
    hydrated_column_configs = hydrate_kv_column_configs(
        column_configs,
        enum_set_map=enum_set_map,
    )

    current_rows = normalize_kv_default_rows(
        deepcopy(field.kv_default_rows or []),
        column_configs=hydrated_column_configs,
    )
    proposed_rows = normalize_kv_default_rows(
        proposed_default_rows
        if proposed_default_rows is not None
        else deepcopy(field.kv_default_rows or []),
        column_configs=hydrated_column_configs,
    )

    if proposed_rows != current_rows:
        raise KVValidationError(
            f"字段“{field.label}”已被{usage_target}使用，默认 KV 行已锁定，不能新增、修改或删除"
        )


def ensure_kv_identity_stable(
    field: Any,
    *,
    proposed_field_type: str,
    proposed_json_key: str,
) -> None:
    usage_target = _find_saved_field_usage_target(field)

    if (
        proposed_field_type == KV_FIELD_TYPE
        and not is_kv_field(field)
        and usage_target is not None
    ):
        raise KVValidationError(
            f"字段“{field.label}”已被{usage_target}使用，不能直接改为五列表格类型"
        )

    if not is_kv_field(field):
        return

    usage_target = _find_saved_kv_usage_target(field)
    if usage_target is None:
        return

    if proposed_field_type != KV_FIELD_TYPE:
        raise KVValidationError(
            f"字段“{field.label}”已被{usage_target}使用，不能改为非五列表格类型"
        )

    if proposed_json_key != field.json_key:
        raise KVValidationError(
            f"字段“{field.label}”已被{usage_target}使用，不能修改 JSON 键名"
        )


def _find_saved_kv_usage_target(field: Any) -> str | None:
    return _find_saved_field_usage_target(field)


def get_saved_kv_usage_target(field: Any) -> str | None:
    return _find_saved_kv_usage_target(field)


def get_saved_field_usage_target(field: Any) -> str | None:
    return _find_saved_field_usage_target(field)


def ensure_field_can_be_deleted(field: Any) -> None:
    usage_target = _find_saved_field_usage_target(field)
    if usage_target is not None:
        raise KVValidationError(f"字段“{field.label}”已被{usage_target}使用，不能删除")


def _find_saved_field_usage_target(field: Any) -> str | None:
    bindings = (
        db.session.execute(
            db.select(project_functions).where(
                project_functions.c.function_config_id == field.function_config_id,
            )
        )
        .mappings()
        .all()
    )

    for binding in bindings:
        pm_fields = (
            binding["pm_fields"] if isinstance(binding["pm_fields"], dict) else {}
        )
        if field.json_key in pm_fields:
            return f"项目 #{binding['project_id']}"

    for task_group in TaskGroup.query.filter_by(
        function_config_id=field.function_config_id
    ).all():
        inputs = task_group.inputs if isinstance(task_group.inputs, dict) else {}
        if field.json_key in inputs:
            return f"任务组 #{task_group.id}"

    return None


def _extract_task_inherited_rows(rows: Any) -> list[dict[str, Any]]:
    if not isinstance(rows, list):
        return []

    inherited_rows = []
    for raw_row in rows:
        if not isinstance(raw_row, dict):
            continue

        source_stage = raw_row.get("source_stage") or KV_STAGE_ADMIN
        if source_stage in {KV_STAGE_ADMIN, KV_STAGE_PROJECT}:
            inherited_rows.append(deepcopy(raw_row))

    return inherited_rows


def _coerce_legacy_inherited_rows(
    rows: Any,
    reference_rows: list[dict[str, Any]],
) -> Any:
    if not isinstance(rows, list):
        return rows

    reference_by_id = {
        row.get("row_id"): row
        for row in reference_rows
        if isinstance(row, dict) and row.get("row_id")
    }

    normalized_rows = []
    for raw_row in rows:
        if not isinstance(raw_row, dict):
            normalized_rows.append(raw_row)
            continue

        row = deepcopy(raw_row)
        row_id = row.get("row_id")
        source_stage = row.get("source_stage") or KV_STAGE_ADMIN
        base_row = reference_by_id.get(row_id)

        if base_row and source_stage in {KV_STAGE_ADMIN, KV_STAGE_PROJECT}:
            row_remark = row.get("remark") or ""
            row_remark3 = row.get("remark3") or ""
            base_remark = base_row.get("remark") or ""
            base_remark3 = base_row.get("remark3") or ""

            if (
                not row_remark3
                and base_remark3
                and row_remark == base_remark3
                and row.get("key") == base_row.get("key")
                and row.get("value") == base_row.get("value")
            ):
                row["remark"] = base_remark
                row["remark3"] = base_remark3

        normalized_rows.append(row)

    return normalized_rows

