from app import db

functions_bp = Blueprint("functions", __name__)


def check_admin(user):
    """检查是否为管理员"""
    return user.role == "admin"


def _build_kv_enum_set_map(payload, existing_field=None):
    requested_ids = get_kv_column_config_enum_ids(payload.get("kv_column_configs"))
    if existing_field is not None:
        requested_ids.update(
            get_kv_column_config_enum_ids(existing_field.kv_column_configs)
        )

    if not requested_ids:
        return {}

    enum_sets = KVEnumSet.query.filter(KVEnumSet.id.in_(requested_ids)).all()
    return {enum_set.id: enum_set for enum_set in enum_sets}


def _get_function_usage_counts(function_id):
    bound_project_count = (
        db.session.execute(
            db.select(db.func.count())
            .select_from(project_functions)
            .where(project_functions.c.function_config_id == function_id)
        ).scalar()
        or 0
    )
    task_group_count = TaskGroup.query.filter_by(function_config_id=function_id).count()
    return {
        "bound_project_count": bound_project_count,
        "task_group_count": task_group_count,
    }


