@jwt_required()
def delete_function(id):
    """删除功能"""
    current_user_id = get_jwt_identity()
    current_user = User.query.get(current_user_id)

    if not check_admin(current_user):
        return jsonify({"message": "无权删除功能"}), 403

    func = FunctionConfig.query.get(id)
