def _ensure_stage_values(data, field_name):
    values = data.get(field_name)
    if values is None:
        return {}
    if not isinstance(values, dict):
        raise KVValidationError(f"{field_name} 必须是对象")
    return dict(values)


def _clone_stage_value(value):
    return deepcopy(value)


def _get_system_field_value(field_type, project):
    if field_type == "project_name":
        return project.name or ""
    if field_type == "customer_project_no":
        return project.customer_project_no or ""
    if field_type == "huaxin_project_no":
        return project.huaxin_project_no or ""
    return None


def _parse_default_field_value(field):
    default_value = getattr(field, "default_value", None)
    if default_value is None or default_value == "":
        return None

    if field.field_type == "number":
        try:
            number = float(default_value)
        except (TypeError, ValueError):
            return default_value
        return int(number) if number.is_integer() else number

    if field.field_type == "switch":
        return default_value == "true" or default_value is True

    if field.field_type in {"multiselect", "checkbox"}:
        if isinstance(default_value, list):
            return _clone_stage_value(default_value)
        if isinstance(default_value, str):
            return [item.strip() for item in default_value.split(",") if item.strip()]
        return []

    return _clone_stage_value(default_value)


def _get_empty_field_value(field):
    if field.field_type in {"kv", "file", "multiselect", "checkbox"}:
        return []
    if field.field_type == "number":
        return None
    if field.field_type == "switch":
        return False
    return ""


def _normalize_stage_values(
    function_config, raw_values, *, stage, project, inherited_values=None
):
    allowed_keys = {field.json_key for field in function_config.fields}
    normalized_values = {
        key: _clone_stage_value(value)
        for key, value in raw_values.items()
        if key in allowed_keys
    }
    inherited_values = inherited_values if isinstance(inherited_values, dict) else {}

    for field in function_config.fields:
        system_value = _get_system_field_value(field.field_type, project)
        if system_value is not None:
            normalized_values[field.json_key] = system_value
            continue

        if not is_kv_field(field):
            if field.json_key in normalized_values:
                continue
            if field.json_key in inherited_values:
                normalized_values[field.json_key] = _clone_stage_value(
                    inherited_values[field.json_key]
                )
                continue

            default_value = _parse_default_field_value(field)
            if default_value is not None:
                normalized_values[field.json_key] = default_value
            else:
                normalized_values[field.json_key] = _get_empty_field_value(field)
            continue

        enum_set_ids = get_kv_column_config_enum_ids(field.kv_column_configs)
        enum_sets = (
            KVEnumSet.query.filter(KVEnumSet.id.in_(enum_set_ids)).all()
            if enum_set_ids
            else []
        )
        column_configs = hydrate_kv_column_configs(
            field.kv_column_configs,
            enum_set_map={enum_set.id: enum_set for enum_set in enum_sets},
        )

        inherited_rows = field.kv_default_rows or []
        allow_new_rows = field.fill_stage_project
        if stage == KV_STAGE_TASK:
            inherited_rows = inherited_values.get(field.json_key, inherited_rows)
            allow_new_rows = field.fill_stage_task

        normalized_values[field.json_key] = normalize_kv_stage_rows(
            raw_values.get(field.json_key),
            inherited_rows,
            stage=stage,
            allow_new_rows=allow_new_rows,
            required=field.required,
            column_configs=column_configs,
        )

    return normalized_values


