def _normalize_kv_enum_payload(data, *, existing_enum=None):
    code = (
        data.get("code") if "code" in data else getattr(existing_enum, "code", None)
    ) or ""
    name = (
        data.get("name") if "name" in data else getattr(existing_enum, "name", None)
    ) or ""
    description = (
        data.get("description")
        if "description" in data
        else getattr(existing_enum, "description", "")
    )
    raw_options = (
        data.get("options")
        if "options" in data
        else getattr(existing_enum, "options", [])
    )

    code = code.strip() if isinstance(code, str) else ""
    name = name.strip() if isinstance(name, str) else ""
    description = description.strip() if isinstance(description, str) else ""

    if not code:
        raise ValueError("枚举编码不能为空")
    if not name:
        raise ValueError("枚举名称不能为空")
    if not isinstance(raw_options, list):
        raise ValueError("枚举值必须是数组")

    options = []
    seen_options = set()
    for index, option in enumerate(raw_options, start=1):
        if not isinstance(option, str):
            raise ValueError(f"第 {index} 个枚举值必须为字符串")
        normalized_option = option.strip()
        if not normalized_option:
            raise ValueError(f"第 {index} 个枚举值不能为空")
        if normalized_option in seen_options:
            raise ValueError(f"枚举值重复：{normalized_option}")
        seen_options.add(normalized_option)
        options.append(normalized_option)

    if not options:
        raise ValueError("请至少添加 1 个枚举值")

    return {
        "code": code,
        "name": name,
        "description": description,
        "options": options,
    }


def _is_kv_enum_in_use(enum_set_id):
    for field in FunctionField.query.filter_by(field_type="kv").all():
        if enum_set_id in get_kv_column_config_enum_ids(field.kv_column_configs):
            return True
    return False


