@jwt_required()
def update_kv_enum(enum_id):
    current_user = _get_admin_user()
    if not current_user:
        return jsonify({"message": "无权访问"}), 403

    enum_set = KVEnumSet.query.get(enum_id)
    if not enum_set:
        return jsonify({"message": "枚举不存在"}), 404

    data = request.get_json() or {}
    try:
        payload = _normalize_kv_enum_payload(data, existing_enum=enum_set)
    except ValueError as exc:
        return jsonify({"message": str(exc)}), 400

    existing = KVEnumSet.query.filter(
        KVEnumSet.code == payload["code"],
        KVEnumSet.id != enum_id,
    ).first()
    if existing:
        return jsonify({"message": "枚举编码已存在"}), 400

    override_enum = SimpleNamespace(
        id=enum_id,
        code=payload["code"],
        name=payload["name"],
        options=payload["options"],
    )
    referencing_fields = [
        field
        for field in FunctionField.query.filter_by(field_type="kv").all()
        if enum_id in get_kv_column_config_enum_ids(field.kv_column_configs)
    ]

    try:
        for field in referencing_fields:
            ensure_kv_usage_compatible(
                field,
                enum_set_overrides={enum_id: override_enum},
            )
    except KVValidationError as exc:
        return jsonify({"message": str(exc)}), 400

    enum_set.code = payload["code"]
    enum_set.name = payload["name"]
    enum_set.description = payload["description"]
    enum_set.options = payload["options"]
    db.session.commit()
    return jsonify(enum_set.to_dict())


