export const cloneSerializable = (value, fallback = {}) => {
  if (value === undefined) {
    return fallback
  }

  return JSON.parse(JSON.stringify(value))
}

export const KV_TEXT_COLUMNS = [
  { key: 'key', labelKey: 'kv_key_label', fallbackLabel: '键' },
  { key: 'value', labelKey: 'kv_value_label', fallbackLabel: '值' },
  { key: 'remark', labelKey: 'kv_remark_label', fallbackLabel: '备注' },
  { key: 'remark2', labelKey: 'kv_remark2_label', fallbackLabel: '备注2' },
  { key: 'remark3', labelKey: 'kv_remark3_label', fallbackLabel: '备注3' }
]

export const createDefaultKvColumnConfigs = () => {
  return KV_TEXT_COLUMNS.reduce((configs, column) => {
    configs[column.key] = {
      input_mode: 'direct',
      enum_set_id: null,
      enum_set_name: null,
      enum_set_code: null,
      enum_options: []
    }
    return configs
  }, {})
}

export const normalizeKvColumnConfigs = (configs = {}, enumSets = []) => {
  const defaultConfigs = createDefaultKvColumnConfigs()
  const enumMap = new Map((Array.isArray(enumSets) ? enumSets : []).map(enumSet => [enumSet.id, enumSet]))

  return KV_TEXT_COLUMNS.reduce((result, column) => {
    const rawConfig = configs?.[column.key] || {}
    const inputMode = rawConfig.input_mode === 'enum' ? 'enum' : 'direct'
    const enumSetId = inputMode === 'enum' && Number.isInteger(rawConfig.enum_set_id)
      ? rawConfig.enum_set_id
      : null
    const enumSet = enumMap.get(enumSetId) || null

    result[column.key] = {
      ...defaultConfigs[column.key],
      ...rawConfig,
      input_mode: inputMode,
      enum_set_id: inputMode === 'enum' ? enumSetId : null,
      enum_set_name: enumSet?.name || rawConfig.enum_set_name || null,
      enum_set_code: enumSet?.code || rawConfig.enum_set_code || null,
      enum_options: enumSet?.options
        ? [...enumSet.options]
        : (Array.isArray(rawConfig.enum_options) ? [...rawConfig.enum_options] : [])
    }

    return result
  }, {})
}

export const hasEnabledKvRows = (rows) => {
  return Array.isArray(rows) && rows.some((row) => {
    return Boolean(row?.enabled) && String(row?.key ?? '').trim() && String(row?.value ?? '').trim()
  })
}

export const getKvValidationMessages = (rows, { required = false } = {}) => {
  const normalizedRows = Array.isArray(rows) ? rows : []
  const messages = []

  normalizedRows.forEach((row, index) => {
    const key = String(row?.key ?? '').trim()
    const value = String(row?.value ?? '').trim()

    if (!key || !value) {
      messages.push(`第 ${index + 1} 行需要同时填写键和值`)
    }
  })

  return [...new Set(messages)]
}

const hasInputValue = (value) => {
  if (value === undefined || value === null || value === '') {
    return false
  }

  if (Array.isArray(value)) {
    return value.length > 0
  }

  return true
}

export const materializeKvRowsForStage = (rows, stage) => {
  if (!Array.isArray(rows)) {
    return []
  }

  return rows.map((row) => {
    if (row?.source_stage === stage) {
      return { ...row }
    }

    return { ...row, source_stage: stage }
  })
}

export const buildTaskInputsFromFunctionConfig = ({
  fields = [],
  project = {},
  pmFields = {},
  existingInputs = {}
}) => {
  const nextInputs = cloneSerializable(pmFields, {})
  const currentInputs = cloneSerializable(existingInputs, {})

  Object.entries(currentInputs).forEach(([key, value]) => {
    if (hasInputValue(value) || !hasInputValue(nextInputs[key])) {
      nextInputs[key] = value
    }
  })

  fields.forEach((field) => {
    const key = field.json_key

    if (field.field_type === 'project_name') {
      nextInputs[key] = project.name || ''
      return
    }

    if (field.field_type === 'customer_project_no') {
      nextInputs[key] = project.customer_project_no || ''
      return
    }

    if (field.field_type === 'huaxin_project_no') {
      nextInputs[key] = project.huaxin_project_no || ''
      return
    }

    if (hasInputValue(nextInputs[key])) {
      return
    }

    if (hasInputValue(pmFields[key])) {
      nextInputs[key] = Array.isArray(pmFields[key]) ? cloneSerializable(pmFields[key], []) : pmFields[key]
      return
    }

    if (field.field_type === 'kv') {
