  assert.equal(hasEnabledKvRows([{ key: '', value: false, enabled: true }]), false)
  assert.equal(hasEnabledKvRows([{ key: 0, value: '', enabled: true }]), false)
})

test('getKvValidationMessages allows falsy non-empty values but still rejects empty string', () => {
  const validMessages = getKvValidationMessages([
    { key: 0, value: false, enabled: true }
  ], { required: true })
  assert.deepEqual(validMessages, [])

  const invalidMessages = getKvValidationMessages([
    { key: 0, value: '', enabled: true }
  ], { required: true })
  assert.ok(invalidMessages.includes('第 1 行需要同时填写键和值'))
})

test('getKvValidationMessages treats whitespace-only key/value as empty', () => {
  const messages = getKvValidationMessages([
    { key: '   ', value: '\t', enabled: true },
    { key: '\n', value: '张三', enabled: true }
  ], { required: true })

  assert.ok(messages.includes('第 1 行需要同时填写键和值'))
